nd if not running or token~=runToken then return false,"combo detenido por el usuario"end if LocalPlayer.Character~=character then return false,"el personaje cambió"end local humanoid=character and character:FindFirstChildOfClass("Humanoid")if not humanoid or humanoid.Health<=0 then return false,"el personaje no está vivo"end local targetOK,targetReason=validateLockedComboTarget(character)if not targetOK then return false,targetReason end return true end snapshotPlayingAnimations=function(character)local result={}local humanoid=character and character:FindFirstChildOfClass("Humanoid")local animator=humanoid and humanoid:FindFirstChildOfClass("Animator")if not animator then return result end local ok,tracks=pcall(function()return animator:GetPlayingAnimationTracks()end)if ok and type(tracks)=="table"then for _,track in ipairs(tracks)do if track and track.IsPlaying then result[track]=true end end end return result end hasNewPlayingAnimation=function(character,beforeTracks)local humanoid=character and character:FindFirstChildOfClass("Humanoid")local animator=humanoid and humanoid:FindFirstChildOfClass("Animator")if not animator then return false end local ok,tracks=pcall(function()return animator:GetPlayingAnimationTracks()end)if not ok or type(tracks)~="table"then return false end for _,track in ipairs(tracks)do local priority=track and track.Priority local actionFloor=Enum.AnimationPriority.Action if track and track.IsPlaying and not beforeTracks[track]and priority and priority.Value>=actionFloor.Value then return true end end return false end local function hasStartedKeySkill(step,tool,character,baseline)local cooldown=readCooldown(step.kind,step.key)if cooldown==true and baseline.cooldown==false then return true,"el cooldown pasó de listo a activo"end local holdingObject=tool and tool:FindFirstChild("Holding")local holdingNow=isActiveValue(holdingObject)if holdingNow and not baseline.holding then return true,"Tool.Holding pasó a activo"end local global=select(1,get