ep.kind,tool,step.key,step.hold,token,character,step.aimY or 0.50,step.readyTimeout,step.window)if not(retryableBusy and not castOK and not wasDispatched)then break end if os.clock()>=retryDeadline then castInfo=string.format("NO CONFIRMADO: %s %s siguió bloqueada por Busy/Stun tras %d comprobaciones rápidas; no se envió ninguna entrada.",step.kind,step.key,attempts)retryableBusy=false break end if not alive or not running or token~=runToken then castInfo,retryableBusy="Combo cancelado durante la preparación de "..step.kind.." "..step.key..".",false break end task.wait(math.max(0.008,tonumber(step.retryInterval)or 0.015))until os.clock()>=retryDeadline if retryableBusy and not castOK and not wasDispatched then castInfo=string.format("NO CONFIRMADO: %s %s siguió bloqueada por Busy/Stun durante la ventana de preparación (%d comprobaciones); no se envió ninguna entrada.",step.kind,step.key,attempts)retryableBusy=false end else castOK,castInfo,wasDispatched=castNativeToolSkill(step.kind,tool,step.key,step.hold,token,character,step.aimY or 0.50,step.readyTimeout,step.window)end local shouldSettleHold=(tonumber(step.hold)or 0)>=0.30 and(castOK or wasDispatched)if shouldSettleHold then local settleOK,settleInfo=waitHeldMoveRelease(step,tool,token,character)if not settleOK then setStage(index,"ERROR",tostring(settleInfo),string.format("%.2f",os.clock()-castStarted))return false,settleInfo,wasDispatched end castInfo=tostring(castInfo).."; "..tostring(settleInfo)end local castElapsed=string.format("%.2f",os.clock()-castStarted)if not castOK then local noConfirmation=tostring(castInfo):find("NO CONFIRMADO",1,true)~=nil local wasCooldown=tostring(castInfo):lower():find("cooldown",1,true)~=nil local status=(noConfirmation and wasDispatched)and"ENVIADA?"or(noConfirmation and"NO CONFIRMADO")or(wasCooldown and"OMITIDO")or"ERROR"local detail=tostring(castInfo)if status=="ENVIADA?"then detail="ENTRADA ENVIADA UNA VEZ; inicio local no confirmado. No significa que haya impactado. "..detail end setStage(index,status,detail,castElapsed)return false,detail,wasDispatched end if castOK and step.steerAfterLaunch then local steerOK,steerInfo=steerDragonTalonX(token,character,step)castInfo=tostring(castInfo).."; "..tostring(steerInfo)if not steerOK then setStage(index,"ERROR",tostring(steerInfo),castElapsed)return false,steerInfo,wasDispatched end end if step.after and step.after>0 then task.wait(step.after)end setStage(index,"OK",tostring(castInfo),castElapsed)return true,castInfo,wasDispatched end local function canUseStepForPlan(step,character)local tool=getTool(step.kind)if not tool then return false,"falta la herramienta "..tostring(step.kind)end local requirementsOK,requirementsInfo=checkSkillRequirements(step.kind,tool,step.key,character)if not requirementsOK then return false,requirementsInfo end local cooldown,cooldownReason=readCooldown(step.kind,step.key)if cooldown==true then return false,tostring(step.kind).." "..tostring(step.key).." en cooldown: "..tostring(cooldownReason)end return true,"lista o cooldown no legible"end local function canRunCDKExtension(character)local checks={{kind="CDK",key="Z"},{kind="CDK",key="X"},}for _,candidate in ipairs(checks)do local ok,reason=canUseStepForPlan(candidate,character)if not ok then return false,reason end end return true,"CDK Z y CDK X disponibles para enlazar Talon X -> Talon Z -> C"end local function preflight(token,character)local missing={}for _,kind in ipairs({"Ice","DragonTalon"})do if not getTool(kind)then missing[kind]=true end end if next(missing)then local names={}for kind in pairs(missing)do table.insert(names,kind)end table.sort(names)return false,"Faltan herramientas base: "..table.concat(names,", ")end local iceTool=getTool("Ice")if not findSkillsContainer(iceTool)then return false,"Ice existe en el inventario, pero Main.Skills["..tostring(iceTool.Name).."] aún no está listo."end local awakenedMoves=iceTool:FindFirstChild("AwakenedMoves")if not awakenedMoves or not awakenedMoves:FindFi